<?php declare(strict_types=1);$title='Marketing';require BASE_PATH.'/app/Views/admin/_top.php';$m=$dashboard['metrics'];$a=$dashboard['attribution'];$fmt=static fn(mixed$v,string$suffix='')=>$v===null?'—':number_format((float)$v,2,',','.').$suffix; ?>
<section class="page-heading"><div><p class="eyebrow">Aquisição e atribuição indicativa</p><h1>Marketing</h1><p>Dados sincronizados; o dashboard não consulta APIs externas.</p></div><?php if(can('marketing.connect')):?><div class="action-row"><?php foreach(['meta'=>'Meta','google'=>'Google','tiktok'=>'TikTok']as$provider=>$label):?><form action="<?= e(base_url('admin/marketing/conectar/'.$provider)) ?>" method="post"><?= csrf_field() ?><button class="admin-secondary">Conectar <?= e($label) ?></button></form><?php endforeach;?></div><?php endif;?></section>
<form class="marketing-filters" method="get" action="<?= e(base_url('admin/marketing')) ?>"><select name="periodo"><?php foreach(['hoje'=>'Hoje','ontem'=>'Ontem','7d'=>'Últimos 7 dias','30d'=>'Últimos 30 dias','mes'=>'Mês atual','mes-anterior'=>'Mês anterior']as$key=>$label):?><option value="<?= e($key) ?>" <?= ($_GET['periodo']??'30d')===$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach;?></select><input type="date" name="inicio" value="<?= e($start) ?>"><input type="date" name="fim" value="<?= e($end) ?>"><select name="provider"><option value="">Todos os canais</option><?php foreach(['META','GOOGLE','TIKTOK']as$p):?><option <?= ($filters['provider']??'')===$p?'selected':'' ?>><?= e($p) ?></option><?php endforeach;?></select><select name="integracao_id"><option value="">Todas as contas</option><?php foreach($integrations as$i):?><option value="<?= (int)$i['id'] ?>" <?= (string)($filters['integracao_id']??'')===(string)$i['id']?'selected':'' ?>><?= e($i['provider'].' · '.$i['nome']) ?></option><?php endforeach;?></select><select name="campanha_id"><option value="">Todas as campanhas</option><?php foreach($campaigns as$c):?><option value="<?= (int)$c['id'] ?>" <?= (string)($filters['campanha_id']??'')===(string)$c['id']?'selected':'' ?>><?= e($c['nome']) ?></option><?php endforeach;?></select><select name="modelo"><option value="ultimo">Último contato</option><option value="primeiro" <?= ($filters['modelo']??'')==='primeiro'?'selected':'' ?>>Primeiro contato</option></select><button class="admin-primary">Filtrar</button></form>
<div class="metric-grid marketing-metrics"><div><strong><?= money($m['gasto']) ?></strong><span>Investimento</span></div><div><strong><?= e(number_format((float)($m['impressoes']??0),0,',','.')) ?></strong><span>Impressões</span></div><div><strong><?= $m['alcance']===null?'—':e(number_format((float)$m['alcance'],0,',','.')) ?></strong><span>Alcance</span></div><div><strong><?= e(number_format((float)($m['cliques']??0),0,',','.')) ?></strong><span>Cliques</span></div><div><strong><?= $m['ctr']===null?'—':e($fmt($m['ctr'],'%')) ?></strong><span>CTR</span></div><div><strong><?= $m['cpc']===null?'—':money($m['cpc']) ?></strong><span>CPC</span></div><div><strong><?= $m['cpm']===null?'—':money($m['cpm']) ?></strong><span>CPM</span></div><div><strong><?= e(number_format((float)($a['leads_internos']?:$m['leads']?:0),0,',','.')) ?></strong><span>Leads atribuídos</span></div><div><strong><?= $m['cpl']===null?'—':money($m['cpl']) ?></strong><span>Custo por lead</span></div><div><strong><?= e((string)$a['solicitacoes']) ?></strong><span>Solicitações</span></div><div><strong><?= e((string)$a['reservas_confirmadas']) ?></strong><span>Reservas confirmadas</span></div><div><strong><?= money($a['receita']) ?></strong><span>Receita atribuída</span></div><div><strong><?= $m['custo_reserva']===null?'—':money($m['custo_reserva']) ?></strong><span>Custo por reserva</span></div><div><strong><?= $m['roas']===null?'—':e($fmt($m['roas'],'×')) ?></strong><span>ROAS</span></div><div><strong><?= $m['taxa_conversao']===null?'—':e($fmt($m['taxa_conversao'],'%')) ?></strong><span>Lead → reserva</span></div></div>
<div class="detail-grid"><section class="admin-panel"><h2>Investimento e leads por dia</h2><div class="marketing-timeline"><?php $maxSpend=max(array_map(static fn($r)=>(float)$r['gasto'],$dashboard['daily'])?:[1]);foreach($dashboard['daily']as$row):?><article><time><?= e(date('d/m',strtotime($row['data']))) ?></time><strong><?= e($row['provider']) ?></strong><div><span style="--value:<?= e((string)($maxSpend>0?min(100,(float)$row['gasto']/$maxSpend*100):0)) ?>%"></span></div><small><?= money($row['gasto']) ?> · <?= e((string)($row['leads']??'—')) ?> lead(s)</small></article><?php endforeach;?></div></section><section class="admin-panel"><h2>Comparação entre canais</h2><div class="table-wrap"><table><thead><tr><th>Canal</th><th>Gasto</th><th>Cliques</th><th>Leads</th><th>CPL</th></tr></thead><tbody><?php foreach($dashboard['channels']as$row):?><tr><td><?= e($row['provider']) ?></td><td><?= money($row['gasto']) ?></td><td><?= e((string)$row['cliques']) ?></td><td><?= e((string)($row['leads']??'—')) ?></td><td><?= empty($row['leads'])?'—':money((float)$row['gasto']/(float)$row['leads']) ?></td></tr><?php endforeach;?></tbody></table></div></section></div>
<section class="admin-panel"><h2>Reservas e receita atribuída por dia</h2><div class="table-wrap"><table><thead><tr><th>Data</th><th>Reservas confirmadas</th><th>Receita confirmada</th></tr></thead><tbody><?php foreach($dashboard['attribution_daily']as$row):?><tr><td><?= e(date('d/m/Y',strtotime($row['data']))) ?></td><td><?= e((string)$row['reservas']) ?></td><td><?= money($row['receita']) ?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="admin-panel"><div class="panel-heading"><h2>Integrações</h2><span>Credenciais nunca são exibidas.</span></div><?php if(!$integrations):?><div class="empty-state"><p>Nenhuma conta conectada.</p></div><?php endif;?><?php foreach($integrations as$i):?><article class="integration-card"><div><strong><?= e($i['provider'].' · '.$i['nome']) ?></strong><span class="admin-status status-<?= e(strtolower($i['status'])) ?>"><?= e($i['status']) ?></span><small>Última sincronização: <?= e($i['ultima_sincronizacao_em']?date('d/m/Y H:i',strtotime($i['ultima_sincronizacao_em'])):'Nunca') ?></small><?php if($i['erro_ultima_sincronizacao']):?><p class="error-text"><?= e($i['erro_ultima_sincronizacao']) ?></p><?php endif;?></div><div class="action-row"><?php if(can('marketing.sync')&&$i['status']!=='DESCONECTADA'):?><form action="<?= e(base_url('admin/marketing/integracoes/'.$i['id'].'/sincronizar')) ?>" method="post"><?= csrf_field() ?><input type="hidden" name="inicio" value="<?= e($start) ?>"><input type="hidden" name="fim" value="<?= e($end) ?>"><button class="admin-primary">Sincronizar agora</button></form><form action="<?= e(base_url('admin/marketing/integracoes/'.$i['id'].'/testar')) ?>" method="post"><?= csrf_field() ?><button class="admin-secondary">Testar conexão</button></form><?php endif;?><?php if(can('marketing.connect')&&$i['status']!=='DESCONECTADA'):?><form action="<?= e(base_url('admin/marketing/integracoes/'.$i['id'].'/desconectar')) ?>" method="post" data-confirm="Desconectar e apagar as credenciais desta conta?"><?= csrf_field() ?><button class="admin-danger">Desconectar</button></form><?php endif;?></div></article><?php endforeach;?></section>
<section class="admin-panel"><h2>Campanhas sincronizadas</h2><div class="table-wrap"><table><thead><tr><th>Canal</th><th>Campanha</th><th>Objetivo</th><th>Status</th><th>Orçamento diário</th><th>Sincronizada</th></tr></thead><tbody><?php foreach($campaigns as$c):?><tr><td><?= e($c['provider']) ?></td><td><?= e($c['nome']) ?></td><td><?= e($c['objetivo']?:'—') ?></td><td><?= e($c['status']?:'—') ?></td><td><?= $c['orcamento_diario']===null?'—':money($c['orcamento_diario']) ?></td><td><?= e(date('d/m/Y H:i',strtotime($c['last_synced_at']))) ?></td></tr><?php endforeach;?></tbody></table></div></section>
<p class="privacy-note">A atribuição é indicativa (primeiro ou último contato) e não afirma causalidade quando não há identificador confiável.</p>
